values (10, 'Paket IDC LYD Premium', 'paket-idc-lyd-premium', '/product-image/paket-idc-lyd-premium.webp', ARRAY['/product-image/case-premium.webp']::text[], 'Paket deluxe cetak ID card PVC 2 sisi tajam, casing akrilik keras transparan anti-bengkok, dan tali lanyard tisu custom full color. Solusi nametag awet untuk staf korporat, rumah sakit, dan panitia konferensi di Bandar Lampung (Rajabasa, Sukarame, Kedaton), Jati Agung, Pesawaran, serta Pringsewu.', 30000, NULL, 'ID Card & Lanyard', '[{"minQuantity":1,"price":30000},{"minQuantity":4,"price":28000},{"minQuantity":25,"price":26000},{"minQuantity":100,"price":24000}]'::jsonb, '3-5 hari', 4.9, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 3);
