values (24, 'IDC Lanyard tali Hitam Polos', 'idc-lanyard-tali-hitam-polos', '/product-image/IDC-Tali Hitam.webp', '{}', 'Paket praktis cetak kartu ID card PVC dilengkapi casing dan tali lanyard hitam polos minimalis yang rapi dan profesional. Banyak digunakan untuk kartu tamu gedung, staf operasional, peserta pelatihan, dan panitia acara di Bandar Lampung, Tanjung Karang, Kedaton, dan Kota Metro.', 14000, NULL, 'ID Card & Lanyard', '[{"minQuantity":1,"price":14000},{"minQuantity":50,"price":13000}]'::jsonb, '1-2 hari', 4.6, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 11);
