values (25, 'IDC B4 Lanyard Hitam Polos', 'idc-b4-lanyard-hitam-polos', '/product-image/IDC B4 Lanyard Hitam Polos.webp', '{}', 'Cetak nametag kertas art carton tebal ukuran besar B4 (15,5 x 16,6 cm) lengkap plastik pelindung dan tali lanyard hitam polos. Pilihan paling ekonomis dan jelas terbaca dari jauh untuk co-card panitia konser, turnamen olahraga, ospek kampus, dan pameran di Bandar Lampung, Rajabasa, Sukarame, hingga Metro.', 7000, 5000, 'ID Card & Lanyard', '[{"minQuantity":1,"price":5000}]'::jsonb, '1-2 hari', 4.5, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 12);
