values (26, 'ID Card Yoyo (Tanpa Stiker)', 'id-card-yoyo-tanpa-stiker', '/product-image/New Product/IDC-YOYO-REG.webp', '{}', 'Gantungan yoyo ID card tarik-ulur otomatis untuk tap kartu akses gedung, absensi kantor, dan nametag saku seragam. Ready stock berbagai pilihan warna untuk kebutuhan karyawan rumah sakit, perbankan, dan instansi di Bandar Lampung, Tanjung Karang, Kedaton, serta Jati Agung.', 20000, NULL, 'ID Card & Lanyard', '[{"minQuantity":1,"price":20000},{"minQuantity":10,"price":15000}]'::jsonb, '1-2 hari', 4.7, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 13);
