values (27, 'Stiker ID Card Yoyo Saja', 'stiker-id-card-yoyo-saja', '/product-image/New Product/IDC-YOYO-REG-STIKER.webp', ARRAY['/product-image/New Product/IDC-YOYO-PREM-AK-STIKER.webp', '/product-image/New Product/IDC-YOYO-PREM-SEMI-STIKER.webp']::text[], 'Layanan cetak logo custom presisi untuk ditempel pada bagian tengah yoyo ID card sehingga tampilan seragam kantor, rumah sakit, atau universitas tampak resmi. Melayani pemesanan satuan dan kolektif di Bandar Lampung, Kota Metro, Natar, dan Pringsewu.', 10000, NULL, 'ID Card & Lanyard', '[{"minQuantity":1,"price":10000}]'::jsonb, '2-3 hari', 4.7, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 14);
