values (30, 'ID Card Yoyo Premium Semi Transparan (Tanpa Stiker)', 'id-card-yoyo-premium-semi-transparan-tanpa-stiker', '/product-image/New Product/IDC-YOYO-PREM-SEMI.webp', '{}', 'Gantungan yoyo ID card seri premium dipadukan dengan holder kartu semi-transparan modern yang ringan dan kokoh. Ideal untuk kartu akses pintu elektrik dan tanda pengenal karyawan di Bandar Lampung, Kedaton, Rajabasa, serta Pesawaran.', 25000, NULL, 'ID Card & Lanyard', '[{"minQuantity":1,"price":25000},{"minQuantity":10,"price":23000}]'::jsonb, '2-3 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 16);
