values (34, 'Que Card', 'que-card', '/product-image/que-card.webp', '{}', 'Cetak cue card (que card) panduan MC dan host ukuran A5 ISO (14,8 x 21,0 cm) menggunakan bahan tebal tidak mudah melengkung dengan hasil cetak tajam. Wajib dimiliki untuk pemandu acara seminar, wisuda kampus, pernikahan, dan event formal di Bandar Lampung maupun Kota Metro.', 15000, NULL, 'ID Card & Lanyard', '[{"minQuantity":1,"price":15000}]'::jsonb, '2-3 hari', 4.7, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 17);
