values (2200, 'Casing ID Card', 'casing-id-card', '/product-image/case-variant/case-reguler-color (black, white, semi transparent putih susu, ble, green, red, transparent).jpg', ARRAY['/product-image/case-variant/Case Bening.jpg', '/product-image/case-variant/case-leather kulit.jpg']::text[], 'Tersedia lengkap berbagai varian tempat/casing pelindung ID card ready stock: Case Reguler Warna-warni, Case Bening, Case Putih Susu, Case Akrilik Premium, hingga Case Kulit sintetis. Melayani pembelian eceran mulai Rp 2.000 maupun grosir di Bandar Lampung, Way Hui, Natar, dan sekitarnya.', 2000, NULL, 'ID Card & Lanyard', '[]'::jsonb, 'Ready stock', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[{"code":"Case Reg Merah","image":"/product-image/case-variant/case-reguler-color (black, white, semi transparent putih susu, ble, green, red, transparent).jpg","price":2000},{"code":"Case Reg Hijau","image":"/product-image/case-variant/case-reguler-color (black, white, semi transparent putih susu, ble, green, red, transparent).jpg","price":2000},{"code":"Case Reg Biru","image":"/product-image/case-variant/case-reguler-color (black, white, semi transparent putih susu, ble, green, red, transparent).jpg","price":2000},{"code":"Case Reg Putih","image":"/product-image/case-variant/case-reguler-color (black, white, semi transparent putih susu, ble, green, red, transparent).jpg","price":2000},{"code":"Case Reg Kuning","image":"/product-image/case-variant/case-reguler-color (black, white, semi transparent putih susu, ble, green, red, transparent).jpg","price":2000},{"code":"Case Bening Reg","image":"/product-image/case-variant/Case Bening reg.jfif","price":2000},{"code":"Case Putih Susu","image":"/product-image/case-variant/Case Putih Susu.jfif","price":2000},{"code":"Case Premium","image":"/product-image/case-variant/Case Bening.jpg","price":7000},{"code":"Case Kulit","image":"/product-image/case-variant/case-leather kulit.jpg","price":5000}]'::jsonb, '[]'::jsonb, false, 18);

