values (12, 'X Banner (60x160)', 'x-banner-60x160', '/product-image/X banner 1.webp', ARRAY['/product-image/X banner-2.webp']::text[], 'Paket cetak X-Banner ukuran standar 60 x 160 cm sudah termasuk tiang penyangga lipat dan tas sarung praktis. Solusi display promosi berdiri untuk pintu ruko, kafe, klinik, seminar kampus, dan bazar UMKM di Bandar Lampung, Kemiling, Teluk Betung, Kota Metro, serta Pringsewu.', 90000, NULL, 'Media Promosi', '[{"minQuantity":1,"price":90000},{"minQuantity":4,"price":85000},{"minQuantity":25,"price":80000},{"minQuantity":100,"price":75000}]'::jsonb, '2-3 hari', 4.6, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 20);
