values (13, 'Roll Banner', 'roll-banner', '/product-image/Roll Banner 1.webp', ARRAY['/product-image/Roll Banner 2.webp']::text[], 'Cetak Roll Up Banner gulung otomatis dengan rangka aluminium kokoh dan tampilan tegak rapi berkelas. Sangat cocok untuk booth pameran, lobi kantor, hotel, bank, dan presentasi instansi di Bandar Lampung, Tanjung Karang, Kedaton, maupun Kota Metro.', 350000, NULL, 'Media Promosi', '[{"minQuantity":1,"price":350000},{"minQuantity":4,"price":170000},{"minQuantity":25,"price":160000},{"minQuantity":100,"price":150000}]'::jsonb, '3-4 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 21);
