values (32, 'Cutting Stiker Vinyl A3+', 'cutting-stiker-vinyl-a3', '/product-image/New Product/STIKER-VYNIL.webp', ARRAY['/product-image/New Product/STIKER-VYNIL-2.webp']::text[], 'Cetak stiker bahan vinyl plastik tahan air dan anti-sobek per lembar A3+ lengkap jasa cutting presisi mengikuti lekuk desain. Ideal untuk label produk frozen food, kemasan kopi dingin, stiker helm/motor, dan merchandise event di Bandar Lampung, Kedaton, Sukarame, dan Pringsewu.', 22000, NULL, 'Merchandise', '[{"minQuantity":1,"price":22000}]'::jsonb, '1-2 hari', 4.8, false, 'lembar', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 24);
