values (33, 'Cut Stiker Vynil Papan Bunga', 'cut-stiker-vynil-papan-bunga', '/product-image/vynilcut.webp', '{}', 'Jasa potong cutting stiker vinyl presisi ukuran A3 (27,7 x 42 cm) khusus untuk huruf ucapan papan bunga akrilik, sudah termasuk plastik masking transfer siap tempel. Melayani vendor florist dan pengrajin plakat di Bandar Lampung, Way Hui, Jati Agung, Metro, serta Pesawaran.', 15000, NULL, 'Merchandise', '[{"minQuantity":1,"price":15000},{"minQuantity":4,"price":14000},{"minQuantity":25,"price":13000},{"minQuantity":100,"price":12000}]'::jsonb, '1-2 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 25);
