values (16, 'Ganci Akrilik', 'ganci-akrilik', '/product-image/ganciakrilik-1.webp', ARRAY['/product-image/ganciakrilik-2.webp', '/product-image/ganciakrilik-3.webp']::text[], 'Tempat bikin custom gantungan kunci (ganci) akrilik bening potong laser presisi dengan hasil cetak tajam dan ring besi kuat. Souvenir favorit untuk merchandise komunitas, kenang-kenangan KKN, kado wisuda, dan promosi brand tanpa minimal order di Bandar Lampung, Rajabasa, Kedaton, Tanjung Karang, hingga Kota Metro.', 8000, NULL, 'Merchandise', '[{"minQuantity":1,"price":8000},{"minQuantity":4,"price":7000},{"minQuantity":25,"price":6000},{"minQuantity":100,"price":5000}]'::jsonb, '1-2 hari', 4.5, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 26);
