values (17, 'Ganci 3 cm', 'ganci-3-cm', '/product-image/Ganci-3cm-1.webp', '{}', 'Cetak gantungan kunci bulat diameter 3 cm ringkas dengan laminasi pelindung mengkilap/doff. Pilihan souvenir paling terjangkau mulai Rp 2.300 untuk bagi-bagi hadiah event sekolah, bazar kampus, dan kampanye komunitas di Bandar Lampung, Sukarame, Natar, dan Metro.', 3000, NULL, 'Merchandise', '[{"minQuantity":1,"price":3000},{"minQuantity":4,"price":2700},{"minQuantity":25,"price":2500},{"minQuantity":100,"price":2300}]'::jsonb, '1-2 hari', 4.7, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 27);
