values (18, 'Ganci 5 cm', 'ganci-5-cm', '/product-image/Ganci-5-cm1.webp', '{}', 'Cetak gantungan kunci bulat ukuran lebih besar diameter 5 cm sehingga logo dan ilustrasi terlihat jelas, pengerjaan kilat mulai 1 hari jadi. Cocok untuk merchandise seminar, reuni, dan souvenir organisasi di Bandar Lampung, Tanjung Karang, Kemiling, serta Pringsewu.', 5000, NULL, 'Merchandise', '[{"minQuantity":1,"price":5000},{"minQuantity":4,"price":4500},{"minQuantity":25,"price":4000},{"minQuantity":100,"price":3000}]'::jsonb, '1 hari', 4.6, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 28);
