values (19, 'Ganci Tali', 'ganci-tali', '/product-image/ganci-tali.webp', ARRAY['/product-image/ganci-tali-2.webp']::text[], 'Gantungan kunci tali pendek (keychain lanyard) cetak full color 1 sisi atau 2 sisi yang trendi untuk gantungan kunci motor, mobil, dan resleting tas. Tersedia pemesanan satuan maupun grosir komunitas di Bandar Lampung, Kedaton, Rajabasa, Way Hui, dan Kota Metro.', 4000, NULL, 'Merchandise', '[]'::jsonb, '1-2 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[{"code":"1 Sisi","image":"/product-image/ganci-tali.webp","price":4000},{"code":"2 Sisi","image":"/product-image/ganci-tali.webp","price":5000}]'::jsonb, '[]'::jsonb, false, 29);
