values (103, 'Pin Kait Peniti 3 cm', 'pin-kait-peniti-3-cm', '/product-image/pin-3cm.webp', '{}', 'Cetak pin bulat ukuran mungil 3 cm dengan pengait peniti kuat di bagian belakang untuk aksesoris tas, topi, jilbab, atau tanda peserta kegiatan sekolah dan kampus di Bandar Lampung, Sukarame, Tanjung Karang, hingga Pesawaran.', 3000, NULL, 'Merchandise', '[{"minQuantity":1,"price":3000}]'::jsonb, '1-2 hari', 4.7, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 30);
