values (104, 'Pin Kait Peniti 5 cm', 'pin-kait-peniti-5-cm', '/product-image/pin-5cm.webp', '{}', 'Cetak pin peniti custom diameter 5 cm warna cerah berlaminasi rapi. Sangat cocok untuk tanda panitia, atribut kampanye edukasi, pin organisasi mahasiswa, dan souvenir acara di Bandar Lampung, Rajabasa, Kedaton, Natar, maupun Kota Metro.', 5000, NULL, 'Merchandise', '[{"minQuantity":1,"price":5000}]'::jsonb, '1-2 hari', 4.7, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 31);
