values (21, 'Tumbler Custom', 'tumbler-custom', '/product-image/Insert Paper 1.webp', ARRAY['/product-image/Insert Paper 2.webp', '/product-image/Insert Paper 3.webp']::text[], 'Cetak tumbler botol minum travel custom desain penuh mengelilingi botol, ringan dibawa dan tahan suhu panas maupun dingin. Banyak dipesan untuk seminar kit instansi, hadiah pelanggan, dan souvenir KKN di Bandar Lampung, Sukarame, Rajabasa, serta Lampung Selatan.', 28000, NULL, 'Merchandise', '[{"minQuantity":1,"price":28000},{"minQuantity":2,"price":25000},{"minQuantity":25,"price":23000},{"minQuantity":100,"price":20000}]'::jsonb, '3-5 hari', 4.9, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 33);
