values (22, 'Plakat Akrilik Reg', 'plakat-akrilik-reg', '/product-image/plakat/PKA 004.webp', ARRAY['/product-image/plakat-reg-1.webp', '/product-image/plakat-reg-2.webp', '/product-image/plakat-reg-3.webp', '/product-image/plakat/PKA 005.webp', '/product-image/plakat/PKA 006.webp', '/product-image/plakat/PKA 007.webp']::text[], 'Pembuatan plakat akrilik reguler berkualitas dengan 9 pilihan bentuk desain elegan untuk cenderamata pemateri seminar, kenang-kenangan lokasi KKN/PKL, piala kejuaraan, dan kado wisuda di Bandar Lampung, Way Hui, Kedaton, Kota Metro, dan sekitarnya.', 90000, NULL, 'Merchandise', '[{"minQuantity":1,"price":90000}]'::jsonb, '3-5 hari', 4.9, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[{"code":"PKA004","image":"/product-image/plakat/PKA 004.jpg"},{"code":"PKA005","image":"/product-image/plakat/PKA 005.jpg"},{"code":"PKA006","image":"/product-image/plakat/PKA 006.jpg"},{"code":"PKA007","image":"/product-image/plakat/PKA 007.jpg"},{"code":"PKA008","image":"/product-image/plakat/PKA 008.jpg"},{"code":"PKA009","image":"/product-image/plakat/PKA 009.jpg"},{"code":"PKA010","image":"/product-image/plakat/PKA 010.jpg"},{"code":"PKA011","image":"/product-image/plakat/PKA 011.jpg"},{"code":"PKA012","image":"/product-image/plakat/PKA 012.jpg"}]'::jsonb, '[]'::jsonb, false, 34);
