values (2100, 'Plakat Akrilik UV', 'plakat-akrilik-uv', '/product-image/Merch/Plakat-UV/UV-1.webp', ARRAY['/product-image/Merch/Plakat-UV/UV-2.webp', '/product-image/Merch/Plakat-UV/UV-3.webp']::text[], 'Plakat akrilik premium cetak langsung mesin UV flatbed bertekstur tajam dan awet, tersedia pilihan ketebalan 3 mm hingga 20 mm lengkap dengan kotak box bludru mewah. Standar cenderamata resmi untuk kunjungan dinas, BUMN, universitas, dan penghargaan korporat di Bandar Lampung, Tanjung Karang, Metro, hingga Pringsewu.', 125000, NULL, 'Merchandise', '[]'::jsonb, '3-5 hari', 4.9, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[{"code":"3 mm","image":"/product-image/Merch/Plakat-UV/UV-1.webp","price":125000},{"code":"5 mm","image":"/product-image/Merch/Plakat-UV/UV-1.webp","price":165000},{"code":"8 mm","image":"/product-image/Merch/Plakat-UV/UV-1.webp","price":190000},{"code":"10 mm","image":"/product-image/Merch/Plakat-UV/UV-1.webp","price":200000},{"code":"20 mm","image":"/product-image/Merch/Plakat-UV/UV-1.webp","price":285000}]'::jsonb, '[]'::jsonb, false, 35);

