insert into public.products (id, name, slug, image, additional_images, description, price, discount_price, category, price_thresholds, time, rating, bestseller, unit, is_available, pricing_method, base_price_per_sqm, min_width, max_width, min_height, max_height, models, lamination_options, is_customizable, sort_order)
values (1001, 'Papan Bunga Kecil - Pink Purple Gradient #PKK1', 'papan-bunga-kecil-pink-purple-gradient-pkk1', '/product-image/papan-bunga/Kecil - KODE PKK1 - Pink Purple gradient dengan bunga dan kupu-kupu.webp', '{}', 'Papan bunga akrilik meja ukuran kecil kode #PKK1 bertema gradasi pink-ungu dengan hiasan bunga artificial dan kupu-kupu cantik. Hadiah kekinian awet dipajang untuk ucapan selamat sidang skripsi, wisuda, ulang tahun, dan grand opening toko di Bandar Lampung, Rajabasa, Sukarame, Kedaton, serta Kota Metro.', 65000, NULL, 'Papan Bunga', '[{"minQuantity":1,"price":65000},{"minQuantity":3,"price":63000},{"minQuantity":5,"price":60000}]'::jsonb, '1-2 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 36);
