values (1002, 'Papan Bunga Kecil - Bunga Matahari Mini #PKK3', 'papan-bunga-kecil-bunga-matahari-mini-pkk3', '/product-image/papan-bunga/Kecil - KODE PKK3 dengan Bunga matahari mini dan anggrek putih.webp', '{}', 'Plakat papan bunga akrilik meja kode #PKK3 berhias rangkaian bunga matahari mini dan anggrek putih ceria, custom nama dan foto. Cocok untuk kado wisuda kampus Unila, ITERA, UIN Raden Intan, Malahayati, maupun ucapan selamat pembukaan usaha di Bandar Lampung dan Metro.', 65000, NULL, 'Papan Bunga', '[{"minQuantity":1,"price":65000},{"minQuantity":3,"price":63000},{"minQuantity":5,"price":60000}]'::jsonb, '1-2 hari', 4.9, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 37);
