values (1003, 'Papan Bunga Kecil - Pink Gold Tropical #PKK5', 'papan-bunga-kecil-pink-gold-tropical-pkk5', '/product-image/papan-bunga/Kecil - KODE PKK5 - Pink gold tropical.webp', '{}', 'Papan bunga akrilik meja kode #PKK5 bernuansa pink gold tropical elegan dengan teks ucapan custom sesuai pesanan. Pilihan kado estetik pengganti karangan bunga konvensional untuk area Bandar Lampung, Tanjung Karang, Teluk Betung, Natar, dan sekitarnya.', 65000, NULL, 'Papan Bunga', '[{"minQuantity":1,"price":65000},{"minQuantity":3,"price":63000},{"minQuantity":5,"price":60000}]'::jsonb, '1-2 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 38);
