values (1004, 'Papan Bunga - Plakat Bunga Anggrek Biru #PKB2', 'papan-bunga-plakat-bunga-anggrek-biru-pkb2', '/product-image/papan-bunga/KODE PKB2 - Plakat Bunga dengan anggrek biru moonlight.webp', '{}', 'Plakat papan bunga akrilik eksklusif kode #PKB2 dengan rangkaian anggrek biru moonlight mewah dan dudukan stabil. Sangat cocok untuk hadiah kelulusan, promosi jabatan, peresmian kantor, dan apresiasi relasi bisnis di Bandar Lampung maupun Kota Metro.', 70000, NULL, 'Papan Bunga', '[{"minQuantity":1,"price":70000},{"minQuantity":3,"price":68000},{"minQuantity":5,"price":65000}]'::jsonb, '1-2 hari', 4.9, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 39);
