values (1005, 'Papan Bunga - Plakat Bulat Anggrek Putih #PKB1', 'papan-bunga-plakat-bulat-anggrek-putih-pkb1', '/product-image/papan-bunga/KODE PKB1 - Plakat Bulat dengan bunga anggrek putih.webp', '{}', 'Plakat papan bunga akrilik bentuk bulat kode #PKB1 berpadu hiasan anggrek putih bersih yang anggun. Cocok untuk hadiah pernikahan, pertunangan, wisuda, maupun ucapan pembukaan klinik/kafe di Bandar Lampung, Kedaton, Kemiling, dan Pesawaran.', 70000, NULL, 'Papan Bunga', '[{"minQuantity":1,"price":70000},{"minQuantity":3,"price":68000},{"minQuantity":5,"price":65000}]'::jsonb, '1-2 hari', 4.8, false, 'pcs', true, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb, false, 40);
